<?php
/** Lightweight early-cache health result. @package NakhostinPerformanceEngine */
namespace Nakhostin\PerformanceEngine\EarlyCache;
use Nakhostin\PerformanceEngine\Environment\DropInDetector;
final class EarlyCacheHealthCheck { private $dropins; private $directory; public function __construct( DropInDetector $dropins, string $directory ) { $this->dropins = $dropins; $this->directory = rtrim( $directory, '/\\' ); } public function run(): array { $dropin = $this->dropins->detect(); $writable = is_dir( $this->directory ) ? is_writable( $this->directory ) : is_writable( dirname( $this->directory ) ); return array( 'available' => ( defined( 'WP_CACHE' ) && WP_CACHE ) && ( $this->dropins->can_install() || $dropin['npe_owned'] ), 'installed' => $dropin['npe_owned'], 'dropin_owner' => $dropin['owner'], 'dropin_reason' => $dropin['reason'] ?? 'unknown', 'filesystem_writable' => $writable, 'read_write_healthy' => $this->probe( $writable ), 'config_present' => is_readable( $this->directory . '/early-config.json' ) ); } private function probe( bool $writable ): bool { if ( ! $writable || ! is_dir( $this->directory ) ) { return false; } $token = hash( 'sha256', uniqid( '', true ) ); $path = $this->directory . '/.health-' . substr( $token, 0, 12 ); $payload = substr( $token, 12, 16 ); $ok = false !== file_put_contents( $path, $payload, LOCK_EX ) && is_readable( $path ) && hash_equals( $payload, (string) file_get_contents( $path ) ); if ( is_file( $path ) ) { unlink( $path ); } return $ok; } }
